        { "target", name = "Ephram Barbaro" },
      },
      { only = "Paladin",
        { "text", text = "Murlocs at the Gates" },
        { "text", text = "The Vile Fin murlocs (level 9-11) lurk on the bluffs along the road east of the keep and in the camps around the lake to the south-west, on the way down to Shadowvale." },
        { "goto", x = 17.85, y = 53.43, zone = "1420" },
