        { "text", text = "Hex of Weakness: |cOXP_FRIENDLY_Miles Welsh|r" },
        { "text", text = "At 10 in Thunder Bluff, |cOXP_FRIENDLY_Miles Welsh|r, the priest trainer in the cave under Spirit Rise, hands you a Hex of Weakness letter for |cOXP_FRIENDLY_Ur'kyo|r in Orgrimmar." },
        { "xp", level = 10, text = "Reach level 10" },
        { "goto", x = 25.32, y = 15.27, zone = "1456" },
