        { "target", name = "Dendrite Starblaze" },
        { "fly", inst = 1, name = "Thunder Bluff", text = "Fly to Thunder Bluff", wx = 29.7, wy = -1197.2 },
      },
      { only = "Tauren Druid/Skyborne Druid",
        { "text", text = "Dreadmist Peak" },
        { "text", text = "From the Crossroads head north to Dreadmist Peak and climb to the bubbling |cOXP_PICK_Dreadmist Peak Pool|r on its summit. Burning Blade cultists camp around it: pull them one or two at a time. Stand in the water and use the |cOXP_LOOT_Empty Dreadmist Peak Sampler|r: three Burning Blade Toxicologists (level 13-14, curses and warlock spells) appear and attack. You need not kill them: once the sampler is full, run." },
        { "fly", inst = 1, name = "Crossroads", text = "Fly to Crossroads", wx = -2596.1, wy = -441.8 },
        { "goto", x = 48.4, y = 18.9, zone = "1413" },
        { "complete", obj = 1, quest = 6127, text = "Use |cOXP_LOOT_Empty Dreadmist Peak Sampler|r (|cOXP_LOOT_Empty Dreadmist Peak Sampler|r, standing in the pool)" },
