      { only = "Orc Mage/Troll Mage",
        { "text", text = "Class quest: {quest:1962}" },
        { "text", text = "|cOXP_FRIENDLY_Uthel'nay|r (Orgrimmar)" },
        { "text", text = "|cOXP_FRIENDLY_Uthel'nay|r is one of Orgrimmar's mage trainers, in |cOXP_PICK_Darkbriar Lodge|r in the |cOXP_PICK_Valley of Spirits|r. Then take the zeppelin to Tirisfal Glades from the tower outside Orgrimmar's main gate." },
        { "xp", level = 15, text = "Reach level 15" },
        { "goto", x = 39.16, y = 86.27, zone = "1454" },
        { "accept", quest = 1959, text = "Accept Report to Anastasia" },
        { "target", name = "Uthel'nay" },
      },
      { only = "Scourge Mage",
        { "text", text = "|cOXP_FRIENDLY_Cain Firesong|r (Brill)" },
        { "text", text = "|cOXP_FRIENDLY_Cain Firesong|r is the Brill mage trainer, upstairs in the Gallows' End Tavern: take the stairs inside, the arrow cannot tell the floors apart." },
        { "xp", level = 15, text = "Reach level 15" },
        { "goto", x = 61.97, y = 52.47, zone = "1420" },
        { "accept", quest = 1959, text = "Accept Report to Anastasia" },
        { "target", name = "Cain Firesong" },
      },
      { only = "Mage",
        { "text", text = "|cOXP_FRIENDLY_Anastasia Hartwell|r" },
        { "text", text = "|cOXP_FRIENDLY_Anastasia Hartwell|r stands in the |cOXP_PICK_Magic Quarter|r. The |cOXP_LOOT_Chest of Containment Coffers|r and the |cOXP_LOOT_Cantation of Manifestation|r lie on the ledge behind her (both come back 5 minutes after someone takes them). You hand both in at the end, so keep them." },
        { "goto", x = 85.14, y = 10.03, zone = "1458" },
        { "turnin", quest = 1959, text = "Turn in Report to Anastasia" },
        { "target", name = "Anastasia Hartwell" },
        { "goto", x = 85.14, y = 10.03, zone = "1458" },
        { "accept", quest = 1960, text = "Accept Investigate the Alchemist Shop" },
        { "target", name = "Anastasia Hartwell" },
        { "goto", x = 85.48, y = 9.9, zone = "1458" },
        { "complete", obj = 2, quest = 1960, text = "Chest of Containment Coffers: 1" },
        { "goto", x = 85.65, y = 10.18, zone = "1458" },
        { "complete", obj = 3, quest = 1960, text = "Cantation of Manifestation: 1" },
      },
      { only = "Mage",
        { "text", text = "The alchemist shop" },
        { "text", text = "Algernon's alchemist shop is in the Apothecarium. Stand on the steps or the bridge outside the shop and read the |cOXP_LOOT_Cantation of Manifestation|r: up to four invisible Rift Spawns (level 16-17) appear and attack at once, and the city guards do not help. Hit one with a single-target spell and back off over the bridge: the others give up and fade, the one you hit follows. Beat it down on the shop's half of the bridge (past halfway the coffer will not work on it) until it stops fighting and sits stunned under a spiral, use the |cOXP_LOOT_Chest of Containment Coffers|r on it, then click the |cOXP_LOOT_Filled Containment Coffer|r once it appears on the floor (clicking too early wastes a charge). Three are needed." },
        { "goto", x = 53.2, y = 74.5, zone = "1458" },
        { "item", item = 7308, text = "Use Cantation of Manifestation" },
        { "goto", x = 53.29, y = 74.56, zone = "1458" },
        { "mob", name = "Rift Spawn" },
        { "text", text = "Kill |cOXP_ENEMY_Rift Spawn|r (|cOXP_ENEMY_Rift Spawn|r, down to the stun)" },
        { "goto", x = 53.2, y = 74.5, zone = "1458" },
        { "item", item = 7247, text = "Use Chest of Containment Coffers (|cOXP_LOOT_Chest of Containment Coffers|r, on the stunned |cOXP_ENEMY_Rift Spawn|r)" },
        { "goto", x = 53.2, y = 74.5, zone = "1458" },
        { "complete", obj = 1, quest = 1960, text = "Filled Containment Coffer: 3" },
      },
