        { "text", text = "To Orgrimmar!" },
        { "text", text = "At 16 |cOXP_FRIENDLY_Kaplak|r, the rogue trainer in Razor Hill, sends you to |cOXP_FRIENDLY_Shenthul|r in Orgrimmar." },
        { "xp", level = 16, text = "Reach level 16" },
