        { "target", name = "Mennet Carkad" },
      },
      { only = "Rogue",
        { "text", text = "|cOXP_FRIENDLY_Shenthul|r and Zando'zan" },
        { "text", text = "Undead take the zeppelin from the towers outside the Undercity to Durotar. |cOXP_FRIENDLY_Shenthul|r and Zando'zan stand in the |cOXP_PICK_Cleft of Shadow|r, the canyon under the |cOXP_PICK_Valley of Strength|r. Train Pick Lock from |cOXP_FRIENDLY_Shenthul|r (or any rogue trainer) now if you lack it: this job is a lockpicking test." },
        { "goto", only = "Orc/Troll/Skyborne", x = 43.05, y = 53.74, zone = "1454" },
        { "turnin", only = "Orc/Troll/Skyborne", quest = 2380, text = "Turn in To Orgrimmar!" },
