      { only = "Warrior",
        { "text", text = "|cOXP_FRIENDLY_Ula'elek|r" },
        { "text", text = "|cOXP_FRIENDLY_Ula'elek|r is in Sen'jin Village on the Durotar coast. He wants 7 Uncloven Satyr Hooves." },
        { "goto", x = 56.31, y = 74.33, zone = "1411" },
