        { "text", text = "|cOXP_FRIENDLY_Orm Stonehoof|r" },
        { "text", text = "|cOXP_FRIENDLY_Orm Stonehoof|r works on Thunder Bluff's lowest level, close to the blacksmith." },
        { "goto", x = 38.99, y = 55.98, zone = "1456" },
        { "turnin", quest = 1840, text = "Turn in Orm Stonehoof and the Brutal Helm" },
