      { only = "Tauren Druid/Skyborne Druid", when = { { "onquest", quests = { 30 } } },
        { "text", text = "|cOXP_PICK_Strange Lockbox|r" },
        { "text", text = "From the zeppelin towers, run south into Silverpine and west past the Dead Field to the coast: the |cOXP_PICK_Strange Lockbox|r lies at the bottom of very deep water there, beside an air fissure where you can breathe. Watch your breath on the way down. It holds the |cOXP_LOOT_Half Pendant of Aquatic Endurance|r for Trial of the Sea Lion. Then on to the Sepulcher." },
        { "goto", x = 29.56, y = 29.2, zone = "1421" },
        { "collect", count = 1, item = 15882, text = "Half Pendant of Aquatic Endurance: 1 (|cOXP_LOOT_Half Pendant of Aquatic Endurance|r, from the |cOXP_PICK_Strange Lockbox|r)" },
      },
      {
        { "text", text = "Sepulcher" },
        { "text", text = "Down the road through Silverpine to the Sepulcher: from the zeppelin towers, south through Tirisfal; from the |cOXP_PICK_Strange Lockbox|r, south-east from the coast to the road. |cOXP_FRIENDLY_Shadow Priest Allister|r and |cOXP_FRIENDLY_Apothecary Renferrel|r stand by the crypt entrance." },
        { "goto", x = 42.8, y = 40.86, zone = "1421" },
