        { "text", text = "While you're here: learn Swords from |cOXP_FRIENDLY_Archibald|r (|cOXP_PICK_War Quarter|r, 10 silver); a sword in the main hand levels a Rogue steadily." },
        { "goto", x = 57.31, y = 32.77, zone = "1458" },
        { "train", text = "Train at |cOXP_FRIENDLY_Archibald|r" },
        { "target", name = "Archibald" },
      },
      { only = "Tauren Druid/Skyborne Druid", when = { { "onquest", quests = { 30 } } },
        { "text", text = "Trial of the Sea Lion" },
        { "text", text = "Cast Teleport: Moonglade. Join the two pendant halves at the Shrine of Remulos, on the north-west shore of the lake, before you see |cOXP_FRIENDLY_Dendrite Starblaze|r in Nighthaven. |cOXP_FRIENDLY_Dendrite Starblaze|r stands upstairs in his building: go up inside, the arrow cannot tell the floors apart." },
        { "goto", x = 36, y = 41.42, zone = "1450" },
        { "complete", obj = 1, quest = 30, text = "Pendant of the Sea Lion: 1 (|cOXP_LOOT_Pendant of the Sea Lion|r: use a half at the Shrine of Remulos)" },
        { "goto", x = 56.21, y = 30.64, zone = "1450" },
        { "turnin", quest = 30, text = "Turn in Trial of the Sea Lion" },
        { "target", name = "Dendrite Starblaze" },
      },
      { only = "Tauren Druid/Skyborne Druid", when = { { "turnedin", quest = 30 }, { "turnedin", neg = true, quest = 31 } },
        { "text", text = "Aquatic Form" },
        { "text", text = "Take Aquatic Form from |cOXP_FRIENDLY_Dendrite Starblaze|r, who stands upstairs in his building. Then |cOXP_FRIENDLY_Bunthen Plainswind|r in Nighthaven flies druids to Thunder Bluff: |cOXP_FRIENDLY_Turak Runetotem|r is on Elder Rise." },
        { "goto", x = 56.21, y = 30.64, zone = "1450" },
        { "accept", quest = 31, text = "Accept Aquatic Form" },
        { "target", name = "Dendrite Starblaze" },
        { "fly", inst = 1, name = "Thunder Bluff", text = "Fly to Thunder Bluff (|cOXP_FRIENDLY_Bunthen Plainswind|r in Nighthaven flies druids there)", wx = 29.7, wy = -1197.2 },
        { "goto", x = 76.48, y = 27.22, zone = "1456" },
        { "turnin", quest = 31, text = "Turn in Aquatic Form (|cOXP_FRIENDLY_Turak Runetotem|r: Aquatic Form)" },
        { "target", name = "Turak Runetotem" },
      },
      { only = "Tauren Druid/Skyborne Druid", when = { { "zone", name = "Thunder Bluff" } },
        { "text", text = "Back to the Crossroads" },
        { "text", text = "Train with |cOXP_FRIENDLY_Turak Runetotem|r. Before you fly on, |cOXP_FRIENDLY_Tah Winterhoof|r and |cOXP_FRIENDLY_Zangen Stonehoof|r, a short walk east of the wind rider master, give two quests worked on the next guides' walks; then fly on to the Crossroads, where the next guide starts." },
        { "goto", only = "Druid", x = 76.48, y = 27.22, zone = "1456" },
        { "train", only = "Druid", text = "Train at |cOXP_FRIENDLY_Turak Runetotem|r" },
        { "target", name = "Turak Runetotem", only = "Druid" },
        { "goto", x = 54.14, y = 47.05, zone = "1456" },
        { "accept", quest = 97538, text = "Accept Pigments for Paints (|cOXP_FRIENDLY_Tah Winterhoof|r: Pigments for Paints, the Mirkweed in Mirkfallon Lake by Sun Rock)" },
        { "target", name = "Tah Winterhoof" },
        { "goto", x = 54.97, y = 51.41, zone = "1456" },
        { "accept", optional = true, quest = 1195, text = "Accept The Sacred Flame (|cOXP_FRIENDLY_Zangen Stonehoof|r: The Sacred Flame, the phial from Ashenvale's Laughing Sisters)" },
        { "target", name = "Zangen Stonehoof" },
        { "fly", inst = 1, name = "Crossroads", text = "Fly to Crossroads", wx = -2596.1, wy = -441.8 },
      },
      { when = { { "turnedin", neg = true, quest = 31 } },
