      { only = "Hunter/Shaman",
        { "text", text = "Orgrimmar" },
        { "text", text = "Train before you fly on: the next guide flies from here to the Crossroads." },
        { "goto", only = "Shaman", x = 38.8, y = 36.37, zone = "1454" },
        { "train", only = "Shaman", text = "Train at |cOXP_FRIENDLY_Kardris Dreamseeker|r" },
