        { "text", text = "|cOXP_PICK_Ashenvale Moonwell|r" },
        { "text", text = "South from Raynewood, the moonwell sits in a hollow west of the river, hard to see from the road; Mystral Lake is west of it. Use the |cOXP_LOOT_Etched Phial|r at the moonwell to fill it." },
        { "goto", x = 60.2, y = 72.9, zone = "1440" },
        { "complete", obj = 1, quest = 1195, text = "Use |cOXP_LOOT_Etched Phial|r (|cOXP_LOOT_Etched Phial|r, at the |cOXP_PICK_Ashenvale Moonwell|r)" },
        { "goto", x = 60.2, y = 72.91, zone = "1440" },
        { "complete", obj = 1, quest = 1195, text = "Filled Etched Phial: 1" },
