        { "goto", x = 86.21, y = 15.93, zone = "1458" },
        { "accept", quest = 4739, text = "Accept In Search of Menara Voidrender" },
        { "target", name = "Kaal Soulreaper" },
      },
      { only = "Warlock",
        { "text", text = "|cOXP_LOOT_Robes of Arcana|r and a |cOXP_LOOT_Gold Bar|r" },
        { "text", text = "Tailors sew the |cOXP_LOOT_Robes of Arcana|r from a rare pattern; miners smelt Gold Bars from |cOXP_LOOT_Gold Ore|r. Everyone else buys both at the Auction House. If you wear the robe, take it off: |cOXP_FRIENDLY_Menara Voidrender|r keeps it." },
        { "goto", x = 61.2, y = 71.3, zone = "1453" },
        { "collect", count = 1, item = 5770, text = "Robes of Arcana: 1 (|cOXP_LOOT_Robes of Arcana|r: the Auction House)" },
        { "goto", x = 55.9, y = 62.7, zone = "1454" },
        { "collect", count = 1, item = 5770, text = "Robes of Arcana: 1 (|cOXP_LOOT_Robes of Arcana|r: the Auction House)" },
