        { "mob", name = "Hatefury Trickster" },
        { "mob", name = "Hatefury Felsworn" },
      },
      { only = "Warlock",
        { "text", text = "Mannoroc Coven" },
        { "text", text = "The Lesser Infernals (36-37) and Demon Portal Guardians (38) of Mannoroc Coven, in the south of Desolace, drop the stone half the time. The guide waits for level 35 first: at 31 they are too strong to solo. They resist fire, so use Shadow Bolt and Corruption." },
        { "xp", level = 35, text = "Reach level 35" },
        { "goto", x = 56.8, y = 71.13, zone = "1443" },
        { "complete", obj = 2, quest = 4783, text = "Lesser Infernal Stone: 1" },
        { "mob", name = "Lesser Infernal" },
        { "mob", name = "Demon Portal Guardian" },
      },
