      },
      { only = "Warlock",
        { "text", text = "Fine Gold Thread" },
        { "text", text = "Back to |cOXP_ENEMY_Xizk Goodstitch|r in Booty Bay: he offers Fine Gold Thread as a quest you hand straight back to him. He may show no quest marker; talk to him anyway." },
        { "goto", x = 28.71, y = 76.89, zone = "1434" },
        { "turnin", quest = 4785, text = "Turn in Fine Gold Thread (|cOXP_ENEMY_Xizk Goodstitch|r: Fine Gold Thread, handed straight back)" },
