        { "mob", name = "Dalaran Worker" },
      },
      {
        { "text", text = "Hillsbrad Foothills" },
        { "reach", text = "Azurelode Mine", x = 28.5, y = 55, zone = "1424" },
      },
      {
        { "text", text = "Azurelode Mine" },
        { "text", text = "Head south past Hillsbrad town to the Azurelode Mine. Miners work the tunnels; |cOXP_ENEMY_Foreman Bonds|r (30) and |cOXP_ENEMY_Miner Hackett|r (29) are deep inside." },
        { "goto", x = 28.3, y = 54.8, zone = "1424" },
