      { only = "Druid",
        { "text", text = "Torwa Pathfinder" },
        { "text", text = "Fly to Gadgetzan, ride west to the long ramp down into Un'Goro Crater: |cOXP_FRIENDLY_Torwa Pathfinder|r camps at its foot, in the south-east corner of the crater." },
        { "goto", x = 71.64, y = 75.96, zone = "1449" },
        { "turnin", quest = 9063, text = "Turn in Torwa Pathfinder" },
