        { "goto", x = 66.05, y = 18.53, zone = "1454" },
        { "accept", quest = 8151, text = "Accept The Hunter's Charm" },
        { "target", name = "Ormak Grimshot" },
      },
      { only = "Hunter",
        { "text", text = "|cOXP_FRIENDLY_Ogtinc|r" },
        { "text", text = "|cOXP_FRIENDLY_Ogtinc|r lives on a raised spot on the cliffs at the north-east rim of the Ruins of Eldarath, west-central Azshara. Keep to the high ridges around the ruins: the pit below does not lead up to him. Alliance: fly to Talrendis Point; Horde: fly to Valormok, a short ride west of him." },
        { "goto", x = 11.9, y = 77.59, zone = "1447" },
        { "fp", name = "Talrendis Point", text = "Get the Talrendis Point flight path" },
        { "target", name = "Jarrodenus" },
        { "goto", x = 21.96, y = 49.62, zone = "1447" },
